EXPECTED_BATCH_DIGEST = '7a2f2f6f71efb74627f4f891f108b2548a1a9b2a8584cea684eaa630c6d90d90'


def batch_digest(rows):
    digest = sha256()
    for mask in CANONICAL_MASKS:
        digest.update(f"{mask:02d}:{rows[mask][4]}\n".encode("ascii"))
    return digest.hexdigest()


